00338 {
00339   m_filterHor[0][0][0] = filter<8, false, false, false>;
00340   m_filterHor[0][0][1] = filter<8, false, false, true>;
00341   m_filterHor[0][1][0] = filter<8, false, true, false>;
00342   m_filterHor[0][1][1] = filter<8, false, true, true>;
00343 
00344   m_filterHor[1][0][0] = filter<4, false, false, false>;
00345   m_filterHor[1][0][1] = filter<4, false, false, true>;
