00392 //
00393 // !!! NOTE !!!
00394 //
00395 //  This is the scalar version of the function.
00396 //  If you change the functionality here, consider to switch off the SIMD implementation of this function.
00397 //
00399 template<bool isFirst, bool isLast>
00400 void InterpolationFilter::filterCopy( const ClpRng& clpRng, const Pel *src, int srcStride, Pel *dst, int dstStride, int width, int height, bool biMCForDMVR)
00401 {
00402   int row, col;
00403 
00404   if ( isFirst == isLast )
00405   {
00406     for (row = 0; row < height; row++)
00407     {
00408       for (col = 0; col < width; col++)
00409       {
00410         dst[col] = src[col];
00411         JVET_J0090_CACHE_ACCESS( &src[col], __FILE__, __LINE__ );
00412       }
00413 
00414       src += srcStride;
00415       dst += dstStride;
00416     }
00417   }
00418   else if ( isFirst )
00419   {
00420     const int shift = IF_INTERNAL_FRAC_BITS(clpRng.bd);
00421 
00422     if (biMCForDMVR)
00423     {
00424       int shift10BitOut, offset;
00425       if ((clpRng.bd - IF_INTERNAL_PREC_BILINEAR) > 0)
00426       {
00427         shift10BitOut = (clpRng.bd - IF_INTERNAL_PREC_BILINEAR);
00428         offset = (1 << (shift10BitOut - 1));
00429         for (row = 0; row < height; row++)
00430         {
00431           for (col = 0; col < width; col++)
00432           {
00433             dst[col] = (src[col] + offset) >> shift10BitOut;
00434           }
00435           src += srcStride;
00436           dst += dstStride;
00437         }
00438       }
00439       else
00440       {
00441         shift10BitOut = (IF_INTERNAL_PREC_BILINEAR - clpRng.bd);
00442         for (row = 0; row < height; row++)
00443         {
00444           for (col = 0; col < width; col++)
00445           {
00446             dst[col] = src[col] << shift10BitOut;
00447           }
00448           src += srcStride;
00449           dst += dstStride;
00450         }
00451       }
00452     }
00453     else
00454     for (row = 0; row < height; row++)
00455     {
00456       for (col = 0; col < width; col++)
00457       {
00458         Pel val = leftShift_round(src[col], shift);
00459         dst[col] = val - (Pel)IF_INTERNAL_OFFS;
00460         JVET_J0090_CACHE_ACCESS( &src[col], __FILE__, __LINE__ );
00461       }
00462 
00463       src += srcStride;
00464       dst += dstStride;
00465     }
00466   }
00467   else
00468   {
00469     const int shift = IF_INTERNAL_FRAC_BITS(clpRng.bd);
00470 
00471     if (biMCForDMVR)
00472     {
00473       int shift10BitOut, offset;
00474       if ((clpRng.bd - IF_INTERNAL_PREC_BILINEAR) > 0)
00475       {
00476         shift10BitOut = (clpRng.bd - IF_INTERNAL_PREC_BILINEAR);
00477         offset = (1 << (shift10BitOut - 1));
00478         for (row = 0; row < height; row++)
00479         {
00480           for (col = 0; col < width; col++)
00481           {
00482             dst[col] = (src[col] + offset) >> shift10BitOut;
00483           }
00484           src += srcStride;
00485           dst += dstStride;
00486         }
00487       }
00488       else
00489       {
00490         shift10BitOut = (IF_INTERNAL_PREC_BILINEAR - clpRng.bd);
00491         for (row = 0; row < height; row++)
00492         {
00493           for (col = 0; col < width; col++)
00494           {
00495             dst[col] = src[col] << shift10BitOut;
00496           }
00497           src += srcStride;
00498           dst += dstStride;
00499         }
00500       }
00501     }
00502     else
00503     {
00504       for (row = 0; row < height; row++)
00505       {
00506         for (col = 0; col < width; col++)
00507         {
00508           Pel val = src[col];
00509           val     = rightShift_round((val + IF_INTERNAL_OFFS), shift);
00510 
00511           dst[col] = ClipPel(val, clpRng);
00512           JVET_J0090_CACHE_ACCESS(&src[col], __FILE__, __LINE__);
00513         }
00514 
00515         src += srcStride;
00516         dst += dstStride;
00517       }
00518     }
00519   }
00520 }
00521 
00539 //
00540 // !!! NOTE !!!
00541 //
00542 //  This is the scalar version of the function.
00543 //  If you change the functionality here, consider to switch off the SIMD implementation of this function.
00544 //
00546 template<int N, bool isVertical, bool isFirst, bool isLast>
00547 void InterpolationFilter::filter(const ClpRng& clpRng, Pel const *src, int srcStride, Pel *dst, int dstStride, int width, int height, TFilterCoeff const *coeff, bool biMCForDMVR)
00548 {
00549   int row, col;
00550 
00551   Pel c[8];
00552   c[0] = coeff[0];
00553   c[1] = coeff[1];
00554   if ( N >= 4 )
00555   {
00556     c[2] = coeff[2];
00557     c[3] = coeff[3];
00558   }
00559   if ( N >= 6 )
00560   {
00561     c[4] = coeff[4];
00562     c[5] = coeff[5];
00563   }
00564   if ( N == 8 )
00565   {
00566     c[6] = coeff[6];
00567     c[7] = coeff[7];
00568   }
00569 
00570   int cStride = ( isVertical ) ? srcStride : 1;
00571   src -= ( N/2 - 1 ) * cStride;
00572 
00573   int offset;
00574   int headRoom = IF_INTERNAL_FRAC_BITS(clpRng.bd);
00575   int shift    = IF_FILTER_PREC;
00576   // with the current settings (IF_INTERNAL_PREC = 14 and IF_FILTER_PREC = 6), though headroom can be
00577   // negative for bit depths greater than 14, shift will remain non-negative for bit depths of 8->20
00578   CHECK(shift < 0, "Negative shift");
00579 
00580   if ( isLast )
00581   {
00582     shift += (isFirst) ? 0 : headRoom;
00583     offset = 1 << (shift - 1);
00584     offset += (isFirst) ? 0 : IF_INTERNAL_OFFS << IF_FILTER_PREC;
00585   }
00586   else
00587   {
00588     shift -= (isFirst) ? headRoom : 0;
00589     offset = (isFirst) ? -IF_INTERNAL_OFFS << shift : 0;
00590   }
00591 
00592   if (biMCForDMVR)
00593   {
00594     if( isFirst )
00595     {
00596       shift = IF_FILTER_PREC_BILINEAR - (IF_INTERNAL_PREC_BILINEAR - clpRng.bd);
00597       offset = 1 << (shift - 1);
00598     }
00599     else
00600     {
00601       shift = 4;
00602       offset = 1 << (shift - 1);
00603     }
00604   }
00605   for (row = 0; row < height; row++)
00606   {
00607     for (col = 0; col < width; col++)
00608     {
00609       int sum;
00610 
00611       sum  = src[ col + 0 * cStride] * c[0];
00612       sum += src[ col + 1 * cStride] * c[1];
00613       JVET_J0090_CACHE_ACCESS( &src[ col + 0 * cStride], __FILE__, __LINE__ );
00614       JVET_J0090_CACHE_ACCESS( &src[ col + 1 * cStride], __FILE__, __LINE__ );
00615       if ( N >= 4 )
00616       {
00617         sum += src[ col + 2 * cStride] * c[2];
00618         sum += src[ col + 3 * cStride] * c[3];
00619         JVET_J0090_CACHE_ACCESS( &src[ col + 2 * cStride], __FILE__, __LINE__ );
00620         JVET_J0090_CACHE_ACCESS( &src[ col + 3 * cStride], __FILE__, __LINE__ );
00621       }
00622       if ( N >= 6 )
00623       {
00624         sum += src[ col + 4 * cStride] * c[4];
00625         sum += src[ col + 5 * cStride] * c[5];
00626         JVET_J0090_CACHE_ACCESS( &src[ col + 4 * cStride], __FILE__, __LINE__ );
00627         JVET_J0090_CACHE_ACCESS( &src[ col + 5 * cStride], __FILE__, __LINE__ );
00628       }
00629       if ( N == 8 )
00630       {
00631         sum += src[ col + 6 * cStride] * c[6];
00632         sum += src[ col + 7 * cStride] * c[7];
00633         JVET_J0090_CACHE_ACCESS( &src[ col + 6 * cStride], __FILE__, __LINE__ );
00634         JVET_J0090_CACHE_ACCESS( &src[ col + 7 * cStride], __FILE__, __LINE__ );
00635       }
00636 
00637       Pel val = ( sum + offset ) >> shift;
00638       if ( isLast )
00639       {
00640         val = ClipPel( val, clpRng );
00641       }
00642       dst[col] = val;
00643     }
00644 
00645     src += srcStride;
00646     dst += dstStride;
00647   }
00648 }
