00664 template<int N>
00665 void InterpolationFilter::filterHor(const ClpRng& clpRng, Pel const *src, int srcStride, Pel *dst, int dstStride, int width, int height, bool isLast, TFilterCoeff const *coeff, bool biMCForDMVR)
00666 {
00667 //#if ENABLE_SIMD_OPT_MCIF
00668   if( N == 8 )
00669   {
00670     m_filterHor[0][1][isLast](clpRng, src, srcStride, dst, dstStride, width, height, coeff, biMCForDMVR);
00671   }
00672   else if( N == 4 )
00673   {
00674     m_filterHor[1][1][isLast](clpRng, src, srcStride, dst, dstStride, width, height, coeff, biMCForDMVR);
00675   }
00676   else if( N == 2 )
00677   {
00678     m_filterHor[2][1][isLast](clpRng, src, srcStride, dst, dstStride, width, height, coeff, biMCForDMVR);
00679   }
00680   else
00681   {
00682     THROW( "Invalid tap number" );
00683   }
00684 }
