00892 
00893 void InterpolationFilter::xWeightedGeoBlk(const PredictionUnit &pu, const uint32_t width, const uint32_t height, const ComponentID compIdx, const uint8_t splitDir, PelUnitBuf& predDst, PelUnitBuf& predSrc0, PelUnitBuf& predSrc1)
00894 {
00895   Pel*    dst = predDst.get(compIdx).buf;
00896   Pel*    src0 = predSrc0.get(compIdx).buf;
00897   Pel*    src1 = predSrc1.get(compIdx).buf;
00898   int32_t strideDst = predDst.get(compIdx).stride - width;
00899   int32_t strideSrc0 = predSrc0.get(compIdx).stride - width;
00900   int32_t strideSrc1 = predSrc1.get(compIdx).stride - width;
00901 
00902   const char    log2WeightBase = 3;
00903   const ClpRng  clipRng = pu.cu->slice->clpRngs().comp[compIdx];
00904   const int32_t clipbd = clipRng.bd;
00905   const int32_t shiftWeighted = IF_INTERNAL_FRAC_BITS(clipbd) + log2WeightBase;
00906   const int32_t offsetWeighted = (1 << (shiftWeighted - 1)) + (IF_INTERNAL_OFFS << log2WeightBase);
00907   const uint32_t scaleX = getComponentScaleX(compIdx, pu.chromaFormat);
00908   const uint32_t scaleY = getComponentScaleY(compIdx, pu.chromaFormat);
00909 
00910   int16_t angle = g_GeoParams[splitDir][0];
00911   int16_t wIdx = floorLog2(pu.lwidth()) - GEO_MIN_CU_LOG2;
00912   int16_t hIdx = floorLog2(pu.lheight()) - GEO_MIN_CU_LOG2;
00913   int16_t stepX = 1 << scaleX;
00914   int16_t stepY = 0;
00915   int16_t* weight = nullptr;
00916   if (g_angle2mirror[angle] == 2)
00917   {
00918     stepY = -(int)((GEO_WEIGHT_MASK_SIZE << scaleY) + pu.lwidth());
00919     weight = &g_globalGeoWeights[g_angle2mask[angle]][(GEO_WEIGHT_MASK_SIZE - 1 - g_weightOffset[splitDir][hIdx][wIdx][1]) * GEO_WEIGHT_MASK_SIZE + g_weightOffset[splitDir][hIdx][wIdx][0]];
00920   }
00921   else if (g_angle2mirror[angle] == 1)
00922   {
00923     stepX = -1 << scaleX;
00924     stepY = (GEO_WEIGHT_MASK_SIZE << scaleY) + pu.lwidth();
00925     weight = &g_globalGeoWeights[g_angle2mask[angle]][g_weightOffset[splitDir][hIdx][wIdx][1] * GEO_WEIGHT_MASK_SIZE + (GEO_WEIGHT_MASK_SIZE - 1 - g_weightOffset[splitDir][hIdx][wIdx][0])];
00926   }
00927   else
00928   {
00929     stepY = (GEO_WEIGHT_MASK_SIZE << scaleY) - pu.lwidth();
00930     weight = &g_globalGeoWeights[g_angle2mask[angle]][g_weightOffset[splitDir][hIdx][wIdx][1] * GEO_WEIGHT_MASK_SIZE + g_weightOffset[splitDir][hIdx][wIdx][0]];
00931   }
00932   for( int y = 0; y < height; y++ )
00933   {
00934     for( int x = 0; x < width; x++ )
00935     {
00936       *dst++  = ClipPel(rightShift((*weight*(*src0++) + ((8 - *weight) * (*src1++)) + offsetWeighted), shiftWeighted), clipRng);
00937       weight += stepX;
00938     }
00939     dst    += strideDst;
00940     src0   += strideSrc0;
00941     src1   += strideSrc1;
00942     weight += stepY;
00943   }
00944 }
